/* PJ // NETWORK v4
   Notifications, DMs, mentions, threaded comments, search, saves, levels/challenges,
   events, build requests, changelog, PWA, notification sounds, PJ ID Card 2.0 and admin tools.
*/
(()=>{
  if(window.PJNetwork)return;
  const ready=fn=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fn,{once:true}):fn();
  ready(async()=>{
    const TABS=[['home','HOME'],['notifications','NOTIFS'],['dms','DMS'],['search','SEARCH'],['builds','BUILDS'],['events','EVENTS'],['saved','SAVED'],['id','PJ ID'],['admin','ADMIN']];
    const root=document.createElement('section');root.className='pjn-root';root.innerHTML=`
      <button class="pjn-launch" type="button"><i></i><span>PJ // NETWORK</span><b>V4</b><em class="pjn-badge" id="pjnBadge" hidden>0</em></button>
      <div class="pjn-overlay" aria-hidden="true"><div class="pjn-shell" role="dialog" aria-modal="true" aria-label="PJ Network">
        <header class="pjn-head"><div><small>COMMUNITY OS // V4</small><strong>PJ // NETWORK</strong></div><div class="pjn-head-actions"><span><b id="pjnConn">●</b> NETWORK</span><button class="pjn-icon-btn" id="pjnOpenSocial" type="button" title="Open PJ Social">◎</button><button class="pjn-close" id="pjnClose" type="button">×</button></div></header>
        <nav class="pjn-tabs">${TABS.map(([k,n],i)=>`<button type="button" data-tab="${k}" class="${i?'':'active'}">${n}</button>`).join('')}</nav>
        <div class="pjn-status" id="pjnStatus">INITIALIZING NETWORK…</div>
        <main class="pjn-content">
          <section class="pjn-panel active" data-panel="home"><div id="pjnHome"></div></section>
          <section class="pjn-panel" data-panel="notifications"><div class="pjn-section-head"><div><small>NOTIFICATION CENTER</small><h2>What happened while you were away.</h2></div><button class="pjn-btn secondary" id="pjnMarkAll" type="button">MARK ALL READ</button></div><div id="pjnNotifications" class="pjn-stack"></div></section>
          <section class="pjn-panel" data-panel="dms"><div class="pjn-section-head"><div><small>DIRECT MESSAGES</small><h2>Talk one-to-one.</h2></div><span class="pjn-chip warn">NORMAL DMS // SERVER-STORED</span></div><div id="pjnDM"></div></section>
          <section class="pjn-panel" data-panel="search"><div class="pjn-section-head"><div><small>UNIVERSAL SEARCH</small><h2>Search the network.</h2></div></div><div class="pjn-inline"><input class="pjn-search" id="pjnSearchInput" placeholder="People, messages, projects, builds, events…"><button class="pjn-btn" id="pjnSearchBtn" type="button">SEARCH</button></div><div id="pjnSearchResults" class="pjn-search-results"></div></section>
          <section class="pjn-panel" data-panel="builds"><div id="pjnBuilds"></div></section>
          <section class="pjn-panel" data-panel="events"><div id="pjnEvents"></div></section>
          <section class="pjn-panel" data-panel="saved"><div class="pjn-section-head"><div><small>FAVORITES</small><h2>Your saved network items.</h2></div></div><div id="pjnSaved" class="pjn-stack"></div></section>
          <section class="pjn-panel" data-panel="id"><div id="pjnId"></div></section>
          <section class="pjn-panel" data-panel="admin"><div id="pjnAdmin"></div></section>
        </main>
      </div></div>
      <div class="pjn-toast" id="pjnToast"></div>`;
    document.body.appendChild(root);

    const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)],statusEl=$('#pjnStatus'),overlay=$('.pjn-overlay');
    let sb=null,user=null,me=null,ext=null,profiles=[],xpRows=[],admin=false,connected=false,currentTab='home',unread=0,currentThread=null,dmChannel=null,netChannel=null,installPrompt=null;
    const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
    const ago=t=>{const d=new Date(t),s=Math.max(0,(Date.now()-d)/1000);if(s<60)return'now';if(s<3600)return Math.floor(s/60)+'m';if(s<86400)return Math.floor(s/3600)+'h';return Math.floor(s/86400)+'d'};
    const slug=s=>String(s||'item').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100)||'item';
    const rank=x=>x>=500?'XYPHER':x>=250?'CORE MEMBER':x>=120?'OPERATOR':x>=50?'EXPLORER':'VISITOR';
    const nextRank=x=>x>=500?500:x>=250?500:x>=120?250:x>=50?120:50;
    const safeUrl=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)?u.toString():''}catch(_){return''}};
    const check=r=>{if(r?.error)throw new Error(r.error.message||'Request failed');return r};
    const say=(t,type='')=>{statusEl.textContent=t;statusEl.dataset.type=type};
    const toast=t=>{const e=$('#pjnToast');e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),2200)};
    const open=()=>{overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');refreshTab().catch(console.error)};
    const close=()=>{overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true')};
    $('.pjn-launch').onclick=open;$('#pjnClose').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close()};$('#pjnOpenSocial').onclick=()=>window.PJSocial?.open?.();
    $$('.pjn-tabs button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
    function switchTab(k){currentTab=k;$$('.pjn-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===k));$$('.pjn-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===k));refreshTab().catch(console.error)}
    async function refreshTab(){if(!connected)return;if(currentTab==='home')await renderHome();if(currentTab==='notifications')await loadNotifications();if(currentTab==='dms')await renderDM();if(currentTab==='builds')await renderBuilds();if(currentTab==='events')await renderEvents();if(currentTab==='saved')await loadSaved();if(currentTab==='id')await renderId();if(currentTab==='admin')await renderAdmin()}

    async function sdk(){if(window.supabase?.createClient)return window.supabase;await new Promise((res,rej)=>{let s=document.querySelector('script[data-pj-supabase-sdk]');if(s){if(window.supabase?.createClient)return res();s.addEventListener('load',res,{once:true});s.addEventListener('error',rej,{once:true});return}s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.async=true;s.dataset.pjSupabaseSdk='1';s.onload=res;s.onerror=()=>rej(new Error('Supabase SDK failed'));document.head.appendChild(s)});return window.supabase}
    async function connect(){const cfg=window.PJ_SUPABASE_CONFIG;if(!cfg?.url||!cfg?.publishableKey){say('NETWORK SETUP // SUPABASE CONFIG MISSING','error');return}try{const S=await sdk();sb=S.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});let ses=(await sb.auth.getSession()).data.session;if(!ses){const a=await sb.auth.signInAnonymously();if(a.error)throw a.error;ses=a.data.session}user=ses?.user;if(!user)throw new Error('No session');const probe=await sb.from('net_profile_ext').select('user_id').limit(1);if(probe.error&&/does not exist|schema cache|relation/i.test(probe.error.message)){say('PJ NETWORK READY // RUN pj-network-v4.sql IN SUPABASE','warn');window.PJNetwork={open,close,get state(){return{connected:false,setup:'migration-required',uid:user?.id||null}}};registerPWA();return}check(probe);connected=true;await loadIdentity();await ensureExt();await loadBase();await checkAdmin();await loadUnread();wireRealtime();wireMentionBridges();registerPWA();enhanceProjectCards();await autoChallenges();say('PJ // NETWORK ONLINE','ok');await renderHome()}catch(e){console.error('PJ Network',e);say('NETWORK CONNECTION FAILED // CHECK MIGRATION','error')}}
    async function loadIdentity(){const r=await sb.from('public_profiles').select('*').eq('user_id',user.id).maybeSingle();check(r);me={userId:user.id,displayName:r.data?.display_name||'Visitor',handle:r.data?.handle||'@visitor',avatar:r.data?.avatar||'◈',country:r.data?.country||'',bio:r.data?.bio||'',joined:r.data?.created_at||new Date().toISOString()}}
    async function ensureExt(){let r=await sb.from('net_profile_ext').select('*').eq('user_id',user.id).maybeSingle();check(r);if(!r.data){r=await sb.from('net_profile_ext').insert({user_id:user.id}).select().single();check(r)}ext=r.data}
    async function loadBase(){const [p,x]=await Promise.all([sb.from('public_profiles').select('*').limit(300),sb.from('net_xp').select('*').limit(300)]);check(p);check(x);profiles=p.data||[];xpRows=x.data||[]}
    async function checkAdmin(){const r=await sb.from('site_admins').select('user_id').eq('user_id',user.id).maybeSingle();admin=!r.error&&!!r.data}
    const profileOf=uid=>profiles.find(p=>p.user_id===uid)||{display_name:'Visitor',handle:'@visitor',avatar:'◈'};
    const xpOf=uid=>xpRows.find(x=>x.user_id===uid)?.xp||0;

    async function playSound(){if(ext?.sound_theme==='off')return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);const theme=ext?.sound_theme||'pulse';o.type=theme==='soft'?'sine':theme==='arcade'?'square':'triangle';o.frequency.setValueAtTime(theme==='arcade'?620:theme==='soft'?440:520,ctx.currentTime);if(theme==='pulse')o.frequency.exponentialRampToValueAtTime(760,ctx.currentTime+.08);g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.035,ctx.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.13);o.start();o.stop(ctx.currentTime+.14);setTimeout(()=>ctx.close(),250)}catch(_){}}
    async function loadUnread(){const r=await sb.from('net_notifications').select('id',{count:'exact',head:true}).is('read_at',null).eq('recipient_id',user.id);if(!r.error){unread=r.count||0;const b=$('#pjnBadge');b.textContent=unread>99?'99+':String(unread);b.hidden=!unread}}
    async function notify(recipient,kind,entityType,entityKey,body){if(!recipient||recipient===user.id)return;const r=await sb.from('net_notifications').insert({recipient_id:recipient,actor_id:user.id,kind,entity_type:entityType||'',entity_key:String(entityKey||'').slice(0,160),body:String(body||'Notification').slice(0,220)});if(r.error)console.warn('Notification:',r.error.message)}
    async function handleMentions(text,entityType,entityKey){const found=[...new Set((String(text||'').match(/@[a-zA-Z0-9_]+/g)||[]).map(x=>x.toLowerCase()))];if(!found.length)return;for(const h of found){const p=profiles.find(x=>String(x.handle||'').toLowerCase()===h);if(p&&p.user_id!==user.id)await notify(p.user_id,'mention',entityType,entityKey,`${me.displayName} mentioned you: ${String(text).slice(0,110)}`)}}
    async function loadNotifications(){let r=await sb.from('net_notifications').select('*').eq('recipient_id',user.id).order('created_at',{ascending:false}).limit(100);check(r);const box=$('#pjnNotifications'),rows=r.data||[];box.innerHTML=rows.length?rows.map(n=>`<article class="pjn-row pjn-notification ${n.read_at?'':'unread'}"><div class="pjn-row-main"><strong>${esc(n.body)}</strong><small>${esc(n.kind.toUpperCase())} // ${ago(n.created_at)}</small></div><div class="pjn-row-actions">${n.read_at?'':'<button class="pjn-mini secondary" data-read="'+n.id+'">READ</button>'}<button class="pjn-mini secondary" data-save-notif="${n.id}" data-label="${esc(n.body)}">SAVE</button></div></article>`).join(''):'<div class="pjn-empty">NO NOTIFICATIONS YET.</div>';box.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>markRead(b.dataset.read));box.querySelectorAll('[data-save-notif]').forEach(b=>b.onclick=()=>saveItem('notification',b.dataset.saveNotif,b.dataset.label));await loadUnread()}
    async function markRead(id){const r=await sb.from('net_notifications').update({read_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',user.id);check(r);await loadNotifications()}
    $('#pjnMarkAll').onclick=async()=>{if(!connected)return;const r=await sb.from('net_notifications').update({read_at:new Date().toISOString()}).eq('recipient_id',user.id).is('read_at',null);check(r);await loadNotifications()};

    function progressPct(x){const n=nextRank(x),floor=x>=250?250:x>=120?120:x>=50?50:0;return x>=500?100:Math.max(0,Math.min(100,((x-floor)/(n-floor))*100))}
    async function renderHome(){await loadBase();const x=xpOf(user.id),rnk=rank(x);const [ch,done,pins]=await Promise.all([sb.from('net_challenges').select('*').eq('active',true),sb.from('net_challenge_completions').select('*').eq('user_id',user.id),sb.from('net_pins').select('*').order('created_at',{ascending:false}).limit(6)]);[ch,done,pins].forEach(check);const doneSet=new Set((done.data||[]).map(x=>x.challenge_id));const stats=await communityStats();$('#pjnHome').innerHTML=`<div class="pjn-grid two"><article class="pjn-card hero"><small>COMMUNITY LEVEL</small><div class="pjn-statline"><div><h2>${esc(rnk)}</h2><p>${x} XP // ${x>=500?'MAX RANK':nextRank(x)+' XP NEXT'}</p></div><div class="pjn-level">${String(Math.floor(x/50)+1).padStart(2,'0')}</div></div><div class="pjn-progress"><i style="width:${progressPct(x)}%"></i></div></article><article class="pjn-card"><small>NETWORK PRESENCE</small><form class="pjn-form" id="pjnSettings"><div class="pjn-grid two"><label>STATUS<select id="pjnAvailability">${['online','busy','coding','gaming','invisible'].map(v=>`<option ${ext.availability===v?'selected':''}>${v}</option>`).join('')}</select></label><label>SOUND THEME<select id="pjnSound">${['pulse','soft','arcade','off'].map(v=>`<option ${ext.sound_theme===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="pjn-grid two"><label>GITHUB URL<input id="pjnGithub" value="${esc(ext.github_url||'')}" placeholder="https://github.com/..."></label><label>WEBSITE URL<input id="pjnWebsite" value="${esc(ext.website_url||'')}" placeholder="https://..."></label><label>SPOTIFY URL<input id="pjnSpotify" value="${esc(ext.spotify_url||'')}" placeholder="https://open.spotify.com/..."></label><label>GAMER TAG<input id="pjnGamer" value="${esc(ext.gamer_tag||'')}" maxlength="80"></label></div><button>SAVE NETWORK PROFILE</button></form></article></div><div class="pjn-grid three" style="margin-top:12px"><article class="pjn-card"><small>NETWORK STATS // THIS MONTH</small><div class="pjn-stack">${Object.entries(stats).map(([k,v])=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(k)}</strong></div><b>${v}</b></div>`).join('')}</div></article><article class="pjn-card"><small>WEEKLY CHALLENGES</small><div class="pjn-stack">${(ch.data||[]).map(c=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(c.title)}</strong><small>+${c.xp} XP</small><p>${esc(c.description)}</p></div>${doneSet.has(c.id)?'<span class="pjn-chip good">DONE</span>':`<button class="pjn-mini" data-challenge="${c.id}">COMPLETE</button>`}</div>`).join('')||'<div class="pjn-empty">NO ACTIVE CHALLENGES.</div>'}</div></article><article class="pjn-card"><small>PINNED BY DEVELOPER</small><div class="pjn-stack">${(pins.data||[]).map(p=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(p.title||p.item_type)}</strong><small>${esc(p.item_type.toUpperCase())}</small></div></div>`).join('')||'<div class="pjn-empty">NOTHING PINNED YET.</div>'}</div></article></div><div class="pjn-grid two" style="margin-top:12px"><article class="pjn-card"><small>APP MODE</small><div class="pjn-install"><div><h3>Install PJ Network</h3><p>Add the portfolio to your home screen for a more app-like launch.</p></div><button class="pjn-btn secondary" id="pjnInstall" type="button">INSTALL / INFO</button></div></article><article class="pjn-card"><small>QUICK ROUTES</small><div class="pjn-inline" style="flex-wrap:wrap;margin-top:10px"><button class="pjn-btn secondary" id="pjnGoSocial" type="button">PJ // SOCIAL</button><button class="pjn-btn secondary" id="pjnGoLounge" type="button">PJ // LOUNGE</button><button class="pjn-btn secondary" id="pjnGoContact" type="button">CONTACT DEV</button></div></article></div>`;
      $('#pjnSettings').onsubmit=saveSettings;$$('[data-challenge]').forEach(b=>b.onclick=()=>completeChallenge(b.dataset.challenge));$('#pjnInstall').onclick=installApp;$('#pjnGoSocial').onclick=()=>window.PJSocial?.open?.();$('#pjnGoLounge').onclick=()=>window.PJLounge?.open?.();$('#pjnGoContact').onclick=()=>{window.PJSocial?.open?.();setTimeout(()=>{document.querySelector('.pjsoc-tabs [data-tab="contact"]')?.click()},120)};
    }
    async function saveSettings(e){e.preventDefault();const row={availability:$('#pjnAvailability').value,sound_theme:$('#pjnSound').value,github_url:safeUrl($('#pjnGithub').value),website_url:safeUrl($('#pjnWebsite').value),spotify_url:safeUrl($('#pjnSpotify').value),gamer_tag:$('#pjnGamer').value.trim().slice(0,80),updated_at:new Date().toISOString()};const r=await sb.from('net_profile_ext').update(row).eq('user_id',user.id).select().single();check(r);ext=r.data;toast('NETWORK PROFILE SAVED')}
    async function completeChallenge(id){const r=await sb.from('net_challenge_completions').insert({challenge_id:id,user_id:user.id});if(r.error&&!/duplicate/i.test(r.error.message))throw new Error(r.error.message);await loadBase();toast('CHALLENGE COMPLETE // XP AWARDED');renderHome()}
    async function communityStats(){const start=new Date();start.setUTCDate(1);start.setUTCHours(0,0,0,0);const q=async(table)=>{const r=await sb.from(table).select('*',{count:'exact',head:true}).gte('created_at',start.toISOString());return r.error?'—':r.count||0};const [comments,builds,dms,events]=await Promise.all([q('net_comments'),q('net_build_requests'),q('net_dm_messages'),q('net_events')]);return{COMMENTS:comments,'BUILD IDEAS':builds,'DM MESSAGES':dms,EVENTS:events}}

    async function dmThreads(){const m=await sb.from('net_dm_members').select('thread_id').eq('user_id',user.id);check(m);const ids=(m.data||[]).map(x=>x.thread_id);if(!ids.length)return[];const [t,allm]=await Promise.all([sb.from('net_dm_threads').select('*').in('id',ids).order('created_at',{ascending:false}),sb.from('net_dm_members').select('*').in('thread_id',ids)]);check(t);check(allm);return(t.data||[]).map(th=>{const others=(allm.data||[]).filter(x=>x.thread_id===th.id&&x.user_id!==user.id);return{...th,others}})}
    async function renderDM(){await loadBase();const threads=await dmThreads();const people=profiles.filter(p=>p.user_id!==user.id);$('#pjnDM').innerHTML=`<div class="pjn-dm-layout"><aside class="pjn-dm-side"><form class="pjn-form" id="pjnNewDM"><label>NEW MESSAGE<select id="pjnDMTarget"><option value="">Choose person…</option>${people.map(p=>`<option value="${p.user_id}">${esc(p.display_name)} (${esc(p.handle)})</option>`).join('')}</select></label><button>START DM</button></form><div class="pjn-stack" style="margin-top:10px">${threads.map(t=>{const p=profileOf(t.others[0]?.user_id);return`<button class="pjn-row" style="width:100%;text-align:left;cursor:pointer" data-thread="${t.id}"><div class="pjn-row-main"><strong>${esc(p.avatar||'◈')} ${esc(p.display_name)}</strong><small>${esc(p.handle)}</small></div></button>`}).join('')||'<div class="pjn-empty">NO DMS YET.</div>'}</div><p style="margin-top:10px">Normal DMs are stored on the server. Use XYPHER private rooms in PJ // LOUNGE when you want browser-encrypted message content.</p></aside><div class="pjn-dm-chat"><div class="pjn-dm-chat-head" id="pjnDMHead">SELECT A CONVERSATION</div><div class="pjn-dm-messages" id="pjnDMMessages"><div class="pjn-empty">CHOOSE OR START A DM.</div></div><form class="pjn-dm-compose" id="pjnDMForm"><input id="pjnDMText" maxlength="1500" placeholder="Message…" ${currentThread?'':'disabled'}><button ${currentThread?'':'disabled'}>SEND</button></form></div></div>`;$('#pjnNewDM').onsubmit=async e=>{e.preventDefault();const id=$('#pjnDMTarget').value;if(id)await startDM(id)};$$('[data-thread]').forEach(b=>b.onclick=()=>openDM(b.dataset.thread));$('#pjnDMForm').onsubmit=sendDM;if(currentThread)await openDM(currentThread)}
    async function startDM(target){const blocked=await sb.from('net_blocks').select('*').or(`and(blocker_id.eq.${user.id},blocked_id.eq.${target}),and(blocker_id.eq.${target},blocked_id.eq.${user.id})`);if(!blocked.error&&blocked.data?.length){toast('DM BLOCKED BY PRIVACY SETTINGS');return}let r=await sb.from('net_dm_threads').insert({created_by:user.id}).select().single();check(r);const id=r.data.id;r=await sb.from('net_dm_members').insert([{thread_id:id,user_id:user.id},{thread_id:id,user_id:target}]);check(r);currentThread=id;await notify(target,'dm','dm',id,`${me.displayName} started a DM with you.`);await renderDM();await openDM(id)}
    async function openDM(id){currentThread=id;const mem=await sb.from('net_dm_members').select('*').eq('thread_id',id);check(mem);const other=(mem.data||[]).find(x=>x.user_id!==user.id),p=profileOf(other?.user_id);$('#pjnDMHead').innerHTML=`${esc(p.avatar||'◈')} ${esc(p.display_name)} <span style="color:#56616a">${esc(p.handle)}</span> <button class="pjn-mini secondary" id="pjnBlockDM" type="button">BLOCK</button>`;$('#pjnDMText').disabled=false;$('#pjnDMForm button').disabled=false;$('#pjnBlockDM').onclick=()=>blockUser(other?.user_id);await loadDMMessages(id);if(dmChannel)sb.removeChannel(dmChannel);dmChannel=sb.channel(`pjn-dm-${id}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'net_dm_messages',filter:`thread_id=eq.${id}`},()=>loadDMMessages(id)).subscribe()}
    async function loadDMMessages(id){const r=await sb.from('net_dm_messages').select('*').eq('thread_id',id).order('created_at',{ascending:true}).limit(200);check(r);const box=$('#pjnDMMessages');if(!box)return;box.innerHTML=(r.data||[]).map(m=>`<div class="pjn-bubble ${m.sender_id===user.id?'mine':''}">${esc(m.body).replace(/\n/g,'<br>')}<small>${esc(profileOf(m.sender_id).display_name)} // ${ago(m.created_at)}</small></div>`).join('')||'<div class="pjn-empty">NO MESSAGES YET.</div>';box.scrollTop=box.scrollHeight}
    async function sendDM(e){e.preventDefault();if(!currentThread)return;const input=$('#pjnDMText'),text=input.value.trim();if(!text)return;const r=await sb.from('net_dm_messages').insert({thread_id:currentThread,sender_id:user.id,body:text.slice(0,1500)});check(r);input.value='';const mem=await sb.from('net_dm_members').select('user_id').eq('thread_id',currentThread);if(!mem.error){for(const m of mem.data||[])if(m.user_id!==user.id)await notify(m.user_id,'dm','dm',currentThread,`${me.displayName}: ${text.slice(0,120)}`)}await handleMentions(text,'dm',currentThread);await loadDMMessages(currentThread)}
    async function blockUser(uid){if(!uid)return;const r=await sb.from('net_blocks').upsert({blocker_id:user.id,blocked_id:uid});check(r);toast('USER BLOCKED');currentThread=null;renderDM()}

    async function saveItem(type,key,label){const r=await sb.from('net_saves').upsert({user_id:user.id,item_type:type,item_key:String(key),label:String(label||'').slice(0,160)});check(r);toast('SAVED')}
    async function loadSaved(){const r=await sb.from('net_saves').select('*').eq('user_id',user.id).order('created_at',{ascending:false});check(r);const box=$('#pjnSaved');box.innerHTML=(r.data||[]).map(s=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(s.label||s.item_key)}</strong><small>${esc(s.item_type.toUpperCase())} // ${ago(s.created_at)}</small></div><button class="pjn-mini secondary" data-unsave-type="${esc(s.item_type)}" data-unsave-key="${esc(s.item_key)}">REMOVE</button></div>`).join('')||'<div class="pjn-empty">NOTHING SAVED YET.</div>';box.querySelectorAll('[data-unsave-key]').forEach(b=>b.onclick=async()=>{const r=await sb.from('net_saves').delete().eq('user_id',user.id).eq('item_type',b.dataset.unsaveType).eq('item_key',b.dataset.unsaveKey);check(r);loadSaved()})}

    async function searchNetwork(){const q=$('#pjnSearchInput').value.trim();if(!q)return;$('#pjnSearchResults').innerHTML='<div class="pjn-empty">SEARCHING…</div>';const like=`%${q.replace(/[%_]/g,'')}%`;const jobs=[['PERSON',sb.from('public_profiles').select('user_id,display_name,handle,bio,country').or(`display_name.ilike.${like},handle.ilike.${like},bio.ilike.${like}`).limit(20)],['LOUNGE',sb.from('lounge_messages').select('id,user_id,display_name,message,created_at').ilike('message',like).limit(20)],['BUILD',sb.from('net_build_requests').select('*').or(`title.ilike.${like},body.ilike.${like}`).limit(20)],['EVENT',sb.from('net_events').select('*').or(`title.ilike.${like},description.ilike.${like}`).limit(20)],['CHANGELOG',sb.from('net_changelog').select('*').or(`title.ilike.${like},body.ilike.${like}`).limit(20)],['COMMENT',sb.from('net_comments').select('*').ilike('body',like).limit(20)]];const settled=await Promise.all(jobs.map(async([type,p])=>{const r=await p;return{type,data:r.error?[]:r.data||[]}}));const results=[];for(const g of settled)for(const x of g.data){let key=x.id||x.user_id||'',label=g.type==='PERSON'?`${x.display_name} ${x.handle}`:g.type==='BUILD'?x.title:g.type==='EVENT'?x.title:g.type==='CHANGELOG'?`${x.version} ${x.title}`:x.message||x.body||'';results.push({type:g.type,key,label:String(label).replace(/^~PJ[LSR]3~/,'').slice(0,180)})}$('#pjnSearchResults').innerHTML=results.length?results.map((r,i)=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(r.label)}</strong><small>${r.type}</small></div><button class="pjn-mini secondary" data-search-save="${i}">SAVE</button></div>`).join(''):'<div class="pjn-empty">NO RESULTS.</div>';$$('[data-search-save]').forEach(b=>{const r=results[+b.dataset.searchSave];b.onclick=()=>saveItem(r.type.toLowerCase(),r.key,r.label)})}
    $('#pjnSearchBtn').onclick=searchNetwork;$('#pjnSearchInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchNetwork()}});

    async function renderBuilds(){await loadBase();const [req,votes,pins]=await Promise.all([sb.from('net_build_requests').select('*').order('created_at',{ascending:false}).limit(100),sb.from('net_build_votes').select('*').limit(2000),sb.from('net_pins').select('*').eq('item_type','build')]);[req,votes,pins].forEach(check);const pinSet=new Set((pins.data||[]).map(x=>x.item_key));const projects=[...document.querySelectorAll('.project-card:not(.coming-soon)')].map(c=>c.querySelector('h3')?.textContent?.trim()).filter(Boolean);$('#pjnBuilds').innerHTML=`<div class="pjn-section-head"><div><small>BUILD REQUESTS BOARD</small><h2>Suggest it. Vote it. Watch it ship.</h2></div></div><div class="pjn-grid two"><article class="pjn-card"><small>SUBMIT AN IDEA</small><form class="pjn-form" id="pjnBuildForm"><label>TITLE<input id="pjnBuildTitle" maxlength="120" required placeholder="What should Pete build?"></label><label>DETAILS<textarea id="pjnBuildBody" maxlength="900" rows="4" placeholder="Why would it be useful or fun?"></textarea></label><button>SUBMIT BUILD REQUEST</button></form></article><article class="pjn-card"><small>STATUS LEGEND</small><div class="pjn-stack" style="margin-top:8px"><span class="pjn-chip">SUGGESTED</span><span class="pjn-chip warn">PLANNED</span><span class="pjn-chip warn">BUILDING</span><span class="pjn-chip good">SHIPPED</span></div><p>Community votes help prioritize ideas; they do not automatically decide what gets built.</p></article></div><div class="pjn-stack" style="margin-top:12px">${(req.data||[]).map(r=>{const p=profileOf(r.user_id),vs=(votes.data||[]).filter(v=>v.request_id===r.id),mine=vs.some(v=>v.user_id===user.id);return`<article class="pjn-card"><div class="pjn-row-main"><small>${pinSet.has(r.id)?'📌 PINNED // ':''}${esc(r.status.toUpperCase())} // ${ago(r.created_at)}</small><h3>${esc(r.title)}</h3><p>${esc(r.body||'')}</p><div class="pjn-inline" style="flex-wrap:wrap"><button class="pjn-mini ${mine?'':'secondary'}" data-vote="${r.id}">▲ ${vs.length}</button><button class="pjn-mini secondary" data-save-build="${r.id}" data-label="${esc(r.title)}">SAVE</button>${admin?`<button class="pjn-mini secondary" data-pin-build="${r.id}" data-label="${esc(r.title)}">${pinSet.has(r.id)?'UNPIN':'PIN'}</button>`:''}<span class="pjn-chip">BY ${esc(p.display_name)}</span></div><div class="pjn-project-comments" data-comments="build:${r.id}"></div></div></article>`}).join('')||'<div class="pjn-empty">NO BUILD REQUESTS YET.</div>'}</div><div class="pjn-section-head" style="margin-top:18px"><div><small>PROJECT COMMENTS</small><h2>Discussions around the builds.</h2></div></div><div class="pjn-grid two">${projects.map(name=>`<article class="pjn-card"><small>PROJECT</small><h3>${esc(name)}</h3><div class="pjn-project-comments" data-comments="project:${slug(name)}"></div></article>`).join('')||'<div class="pjn-empty">NO PROJECT CARDS FOUND.</div>'}</div>`;
      $('#pjnBuildForm').onsubmit=submitBuild;$$('[data-vote]').forEach(b=>b.onclick=()=>toggleVote(b.dataset.vote));$$('[data-save-build]').forEach(b=>b.onclick=()=>saveItem('build',b.dataset.saveBuild,b.dataset.label));$$('[data-pin-build]').forEach(b=>b.onclick=()=>togglePin('build',b.dataset.pinBuild,b.dataset.label));for(const box of $$('[data-comments]')){const [type,key]=box.dataset.comments.split(':');await renderComments(box,type,key)}
    }
    async function submitBuild(e){e.preventDefault();const title=$('#pjnBuildTitle').value.trim(),body=$('#pjnBuildBody').value.trim();if(!title)return;let r=await sb.from('net_build_requests').insert({user_id:user.id,title:title.slice(0,120),body:body.slice(0,900)}).select().single();check(r);await handleMentions(body,'build',r.data.id);await completeChallengeQuiet('build-idea');toast('BUILD REQUEST SUBMITTED');renderBuilds()}
    async function toggleVote(id){let r=await sb.from('net_build_votes').select('*').eq('request_id',id).eq('user_id',user.id).maybeSingle();check(r);if(r.data)r=await sb.from('net_build_votes').delete().eq('request_id',id).eq('user_id',user.id);else{r=await sb.from('net_build_votes').insert({request_id:id,user_id:user.id});const req=await sb.from('net_build_requests').select('user_id,title').eq('id',id).single();if(!req.error)await notify(req.data.user_id,'vote','build',id,`${me.displayName} upvoted “${req.data.title}”.`)}check(r);renderBuilds()}
    async function renderComments(box,type,key){const r=await sb.from('net_comments').select('*').eq('context_type',type).eq('context_key',key).order('created_at',{ascending:true});check(r);const rows=r.data||[],byParent=id=>rows.filter(x=>(x.parent_id||null)===(id||null));const item=c=>{const p=profileOf(c.user_id);return`<div class="pjn-comment"><div class="pjn-comment-head"><span>${esc(p.avatar||'◈')} ${esc(p.display_name)}</span><span>${ago(c.created_at)}</span></div><div class="pjn-comment-body">${esc(c.body)}</div><div class="pjn-comment-actions"><button class="pjn-mini secondary" data-reply-comment="${c.id}" data-name="${esc(p.display_name)}">REPLY</button><button class="pjn-mini secondary" data-save-comment="${c.id}" data-label="${esc(c.body.slice(0,80))}">SAVE</button></div>${byParent(c.id).length?`<div class="pjn-thread">${byParent(c.id).map(item).join('')}</div>`:''}</div>`};box.innerHTML=`<div class="pjn-stack">${byParent(null).map(item).join('')||'<div class="pjn-empty">NO COMMENTS YET.</div>'}</div><form class="pjn-form pjn-comment-form" style="margin-top:8px"><input type="hidden" name="parent"><input name="body" maxlength="1000" placeholder="Add a comment or @mention someone…"><button>POST</button></form>`;box.querySelectorAll('[data-reply-comment]').forEach(b=>b.onclick=()=>{const f=box.querySelector('.pjn-comment-form');f.parent.value=b.dataset.replyComment;f.body.placeholder=`Reply to ${b.dataset.name}…`;f.body.focus()});box.querySelectorAll('[data-save-comment]').forEach(b=>b.onclick=()=>saveItem('comment',b.dataset.saveComment,b.dataset.label));box.querySelector('.pjn-comment-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,text=f.body.value.trim();if(!text)return;const parent=f.parent.value||null;let r=await sb.from('net_comments').insert({context_type:type,context_key:key,parent_id:parent,user_id:user.id,body:text}).select().single();check(r);if(parent){const par=rows.find(x=>x.id===parent);if(par)await notify(par.user_id,'reply',type,key,`${me.displayName} replied: ${text.slice(0,120)}`)}await handleMentions(text,type,key);if(type==='project')await completeChallengeQuiet('explore-project');await renderComments(box,type,key)} }
    async function togglePin(type,key,title){let r=await sb.from('net_pins').select('*').eq('item_type',type).eq('item_key',key).maybeSingle();check(r);if(r.data)r=await sb.from('net_pins').delete().eq('id',r.data.id);else r=await sb.from('net_pins').insert({item_type:type,item_key:key,title,created_by:user.id});check(r);renderBuilds()}

    async function renderEvents(){const [ev,rs,ch]=await Promise.all([sb.from('net_events').select('*').order('starts_at',{ascending:true}).limit(100),sb.from('net_event_rsvps').select('*').limit(1000),sb.from('net_changelog').select('*').order('published_at',{ascending:false}).limit(60)]);[ev,rs,ch].forEach(check);const until=t=>{const ms=new Date(t)-Date.now();if(ms<=0)return'LIVE / STARTED';const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000),m=Math.floor(ms%3600000/60000);return`${d?d+'D ':''}${h}H ${m}M`};$('#pjnEvents').innerHTML=`<div class="pjn-grid two"><div><div class="pjn-section-head"><div><small>EVENTS / LIVE SESSIONS</small><h2>Show up when PJ goes live.</h2></div></div><div class="pjn-stack">${(ev.data||[]).map(e=>{const mine=(rs.data||[]).find(x=>x.event_id===e.id&&x.user_id===user.id),count=(rs.data||[]).filter(x=>x.event_id===e.id).length;return`<article class="pjn-card"><small>${until(e.starts_at)} // ${new Date(e.starts_at).toLocaleString()}</small><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="pjn-inline"><button class="pjn-mini ${mine?'':'secondary'}" data-rsvp="${e.id}">${mine?'RSVP ✓':'RSVP'}</button><button class="pjn-mini secondary" data-save-event="${e.id}" data-label="${esc(e.title)}">SAVE</button><span class="pjn-chip">${count} RSVP</span></div></article>`}).join('')||'<div class="pjn-empty">NO EVENTS SCHEDULED YET.</div>'}</div></div><div><div class="pjn-section-head"><div><small>PUBLIC CHANGELOG</small><h2>What changed.</h2></div></div><div class="pjn-stack">${(ch.data||[]).map(c=>`<article class="pjn-card"><small>${esc(c.version)} // ${new Date(c.published_at).toLocaleDateString()}</small><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p><button class="pjn-mini secondary" data-save-change="${c.id}" data-label="${esc(c.version+' '+c.title)}">SAVE</button></article>`).join('')||'<div class="pjn-empty">NO CHANGELOG ENTRIES.</div>'}</div></div></div>`;$$('[data-rsvp]').forEach(b=>b.onclick=()=>toggleRsvp(b.dataset.rsvp));$$('[data-save-event]').forEach(b=>b.onclick=()=>saveItem('event',b.dataset.saveEvent,b.dataset.label));$$('[data-save-change]').forEach(b=>b.onclick=()=>saveItem('changelog',b.dataset.saveChange,b.dataset.label))}
    async function toggleRsvp(id){let r=await sb.from('net_event_rsvps').select('*').eq('event_id',id).eq('user_id',user.id).maybeSingle();check(r);r=r.data?await sb.from('net_event_rsvps').delete().eq('event_id',id).eq('user_id',user.id):await sb.from('net_event_rsvps').insert({event_id:id,user_id:user.id,status:'going'});check(r);renderEvents()}

    async function renderId(){await loadBase();const x=xpOf(user.id),rnk=rank(x);const [badges,fol]=await Promise.all([tableMaybe('user_badges','*','user_id',user.id),tableMaybe('follows','*',null,null)]);const followerCount=(fol||[]).filter(f=>f.following_id===user.id).length,following=(fol||[]).filter(f=>f.follower_id===user.id).length;$('#pjnId').innerHTML=`<div class="pjn-grid two"><div class="pjn-id-card" id="pjnCard"><div class="pjn-id-top"><div><small>PJ NETWORK // VERIFIED SESSION</small><strong style="display:block;margin-top:5px">IDENTITY CARD 2.0</strong></div><div class="pjn-id-avatar">${esc(me.avatar)}</div></div><div class="pjn-id-body"><small>${esc(rnk)} // LEVEL ${Math.floor(x/50)+1}</small><h2>${esc(me.displayName)}</h2><p>${esc(me.handle)}${me.country?' · '+esc(me.country):''}</p></div><div class="pjn-id-foot"><div><small>XP</small><strong>${x}</strong></div><div><small>BADGES</small><strong>${badges.length}</strong></div><div><small>FOLLOWERS</small><strong>${followerCount}</strong></div><div><small>FOLLOWING</small><strong>${following}</strong></div></div></div><article class="pjn-card"><small>SHAREABLE ID</small><h3>Your public network identity.</h3><p>The card only uses your public Lounge profile, rank and community counts. It does not include private email, exact location or private messages.</p><div class="pjn-inline" style="flex-wrap:wrap"><button class="pjn-btn" id="pjnExportId" type="button">SAVE CARD PNG</button><button class="pjn-btn secondary" id="pjnCopyId" type="button">COPY PROFILE TEXT</button><button class="pjn-btn secondary" id="pjnCopyUid" type="button">COPY MY USER ID</button></div><div class="pjn-stack" style="margin-top:12px">${[ext.github_url,ext.website_url,ext.spotify_url].filter(Boolean).map(u=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(u)}</strong></div></div>`).join('')}${ext.gamer_tag?`<div class="pjn-row"><div class="pjn-row-main"><strong>GAMER // ${esc(ext.gamer_tag)}</strong></div></div>`:''}</div></article></div>`;$('#pjnExportId').onclick=()=>exportIdCard({x,rnk,badges:badges.length,followers:followerCount,following});$('#pjnCopyId').onclick=async()=>{await navigator.clipboard.writeText(`${me.displayName} ${me.handle} // ${rnk} // ${x} XP // PJ Network`);toast('PROFILE TEXT COPIED')};$('#pjnCopyUid').onclick=async()=>{await navigator.clipboard.writeText(user.id);toast('USER ID COPIED')};}
    function exportIdCard(data){const c=document.createElement('canvas');c.width=1200;c.height=675;const x=c.getContext('2d'),accent='#ff2638';x.fillStyle='#050608';x.fillRect(0,0,c.width,c.height);x.strokeStyle='#303840';x.lineWidth=3;x.strokeRect(45,45,1110,585);x.fillStyle=accent;x.fillRect(45,45,12,585);x.font='700 24px monospace';x.fillText('PJ NETWORK // IDENTITY CARD 2.0',90,105);x.fillStyle='#eef2f5';x.font='900 70px system-ui';x.fillText(me.displayName.slice(0,24),90,300);x.fillStyle='#89949c';x.font='500 30px system-ui';x.fillText(`${me.handle}  •  ${data.rnk}`,90,355);x.font='700 24px monospace';x.fillStyle=accent;x.fillText(`${data.x} XP`,90,490);x.fillStyle='#aab4bb';x.fillText(`${data.badges} BADGES`,300,490);x.fillText(`${data.followers} FOLLOWERS`,550,490);x.fillText(`${data.following} FOLLOWING`,850,490);x.fillStyle='#66727a';x.font='500 20px monospace';x.fillText('COMMUNITY RANK ≠ SECURITY CLEARANCE',90,570);x.fillStyle=accent;x.font='900 110px system-ui';x.textAlign='center';x.fillText(me.avatar||'◈',1025,245);x.textAlign='left';const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=`pj-network-${slug(me.handle)}.png`;a.click()}
    async function tableMaybe(table,columns='*',eqCol=null,eqVal=null){try{let q=sb.from(table).select(columns);if(eqCol)q=q.eq(eqCol,eqVal);const r=await q.limit(1000);return r.error?[]:r.data||[]}catch(_){return[]}}

    async function renderAdmin(){if(!admin){$('#pjnAdmin').innerHTML=`<div class="pjn-admin-lock"><div class="pjn-kicker">OWNER CONTROL // LOCKED</div><h2>Admin registration required.</h2><p>The dashboard does not trust usernames or handles. Your actual Supabase user UUID must be registered in <code>site_admins</code>.</p><button class="pjn-btn" id="pjnAdminUid" type="button">COPY MY USER ID</button></div>`;$('#pjnAdminUid').onclick=async()=>{await navigator.clipboard.writeText(user.id);toast('USER ID COPIED')};return}const [inbox,legacy,reports,polls,builds,people]=await Promise.all([sb.from('net_developer_inbox').select('*').order('created_at',{ascending:false}).limit(100),tableQueryMaybe('developer_messages'),tableQueryMaybe('reports'),tableQueryMaybe('polls'),sb.from('net_build_requests').select('*').order('created_at',{ascending:false}).limit(100),sb.from('public_profiles').select('*').limit(300)]);check(inbox);check(builds);check(people);$('#pjnAdmin').innerHTML=`<div class="pjn-section-head"><div><small>OWNER CONTROL</small><h2>Moderation + publishing.</h2></div><span class="pjn-chip good">ADMIN VERIFIED</span></div><div class="pjn-admin-grid"><article class="pjn-card"><small>DEVELOPER INBOX</small><div class="pjn-stack">${[...(inbox.data||[]),...(legacy||[])].map(m=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(m.subject||'Message')}</strong><small>${ago(m.created_at)} // ${esc(m.contact||'NO CONTACT')}</small><p>${esc(m.message||'')}</p></div>${m.status?`<button class="pjn-mini secondary" data-inbox-seen="${m.id}">SEEN</button>`:''}</div>`).join('')||'<div class="pjn-empty">INBOX EMPTY.</div>'}</div></article><article class="pjn-card"><small>REPORTS</small><div class="pjn-stack">${(reports||[]).map(r=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(r.reason||'Report')}</strong><small>${ago(r.created_at)}</small></div><button class="pjn-mini secondary" data-report-clear="${r.id}">CLEAR</button></div>`).join('')||'<div class="pjn-empty">NO OPEN REPORTS.</div>'}</div></article><article class="pjn-card"><small>POLL CONTROL</small><form class="pjn-form" id="pjnPollForm"><input id="pjnPollQ" maxlength="180" placeholder="New poll question"><input id="pjnPollOpts" placeholder="Option 1, Option 2, Option 3"><button>CREATE POLL</button></form><div class="pjn-stack" style="margin-top:8px">${(polls||[]).map(p=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(p.question)}</strong><small>${p.active?'ACTIVE':'CLOSED'}</small></div><button class="pjn-mini secondary" data-poll-toggle="${p.id}" data-active="${p.active}">${p.active?'CLOSE':'OPEN'}</button></div>`).join('')||'<div class="pjn-empty">PJ SOCIAL POLLS NOT INSTALLED OR EMPTY.</div>'}</div></article><article class="pjn-card"><small>PUBLISH</small><form class="pjn-form" id="pjnEventForm"><input id="pjnEventTitle" maxlength="120" placeholder="Event title"><input id="pjnEventTime" type="datetime-local"><textarea id="pjnEventDesc" maxlength="600" rows="3" placeholder="Event details"></textarea><button>CREATE EVENT</button></form><hr style="border:0;border-top:1px solid #20272d;margin:12px 0"><form class="pjn-form" id="pjnChangeForm"><input id="pjnChangeVersion" maxlength="40" placeholder="v4.1"><input id="pjnChangeTitle" maxlength="120" placeholder="Update title"><textarea id="pjnChangeBody" maxlength="1200" rows="3" placeholder="What changed?"></textarea><button>PUBLISH CHANGELOG</button></form></article><article class="pjn-card"><small>BUILD PIPELINE</small><div class="pjn-stack">${(builds.data||[]).map(b=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(b.title)}</strong><small>${esc(b.status.toUpperCase())}</small></div><select data-build-status="${b.id}">${['suggested','planned','building','shipped','rejected'].map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')||'<div class="pjn-empty">NO BUILD REQUESTS.</div>'}</div></article><article class="pjn-card"><small>USER MODERATION</small><div class="pjn-stack">${(people.data||[]).filter(p=>p.user_id!==user.id).slice(0,30).map(p=>`<div class="pjn-row"><div class="pjn-row-main"><strong>${esc(p.display_name)}</strong><small>${esc(p.handle)}</small></div><div class="pjn-row-actions"><button class="pjn-mini secondary" data-mute="${p.user_id}">MUTE 24H</button><button class="pjn-mini secondary" data-unmute="${p.user_id}">CLEAR</button></div></div>`).join('')}</div></article></div>`;
      $$('[data-inbox-seen]').forEach(b=>b.onclick=async()=>{const r=await sb.from('net_developer_inbox').update({status:'seen'}).eq('id',b.dataset.inboxSeen);check(r);renderAdmin()});$$('[data-report-clear]').forEach(b=>b.onclick=async()=>{const r=await sb.from('reports').delete().eq('id',b.dataset.reportClear);check(r);renderAdmin()});$('#pjnPollForm').onsubmit=createPoll;$$('[data-poll-toggle]').forEach(b=>b.onclick=async()=>{const r=await sb.from('polls').update({active:b.dataset.active!=='true'}).eq('id',b.dataset.pollToggle);check(r);renderAdmin()});$('#pjnEventForm').onsubmit=createEvent;$('#pjnChangeForm').onsubmit=createChange;$$('[data-build-status]').forEach(s=>s.onchange=async()=>{const r=await sb.from('net_build_requests').update({status:s.value,updated_at:new Date().toISOString()}).eq('id',s.dataset.buildStatus);check(r);toast('BUILD STATUS UPDATED')});$$('[data-mute]').forEach(b=>b.onclick=()=>muteUser(b.dataset.mute,24));$$('[data-unmute]').forEach(b=>b.onclick=()=>clearSanction(b.dataset.unmute));
    }
    async function tableQueryMaybe(table){try{const r=await sb.from(table).select('*').order('created_at',{ascending:false}).limit(100);return r.error?[]:r.data||[]}catch(_){return[]}}
    async function createPoll(e){e.preventDefault();const q=$('#pjnPollQ').value.trim(),opts=$('#pjnPollOpts').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,6);if(!q||opts.length<2)return toast('ADD A QUESTION + 2 OPTIONS');const r=await sb.from('polls').insert({question:q,options:opts,active:true});check(r);toast('POLL CREATED');renderAdmin()}
    async function createEvent(e){e.preventDefault();const title=$('#pjnEventTitle').value.trim(),time=$('#pjnEventTime').value;if(!title||!time)return;const r=await sb.from('net_events').insert({title,description:$('#pjnEventDesc').value.trim(),starts_at:new Date(time).toISOString(),created_by:user.id});check(r);toast('EVENT PUBLISHED');renderAdmin()}
    async function createChange(e){e.preventDefault();const version=$('#pjnChangeVersion').value.trim(),title=$('#pjnChangeTitle').value.trim(),body=$('#pjnChangeBody').value.trim();if(!version||!title||!body)return;const r=await sb.from('net_changelog').insert({version,title,body,created_by:user.id});check(r);toast('CHANGELOG PUBLISHED');renderAdmin()}
    async function muteUser(uid,hours){const until=new Date(Date.now()+hours*3600000).toISOString();const r=await sb.from('net_user_sanctions').upsert({user_id:uid,muted_until:until,reason:'Temporary community mute',updated_by:user.id,updated_at:new Date().toISOString()});check(r);toast('USER MUTED')}
    async function clearSanction(uid){const r=await sb.from('net_user_sanctions').delete().eq('user_id',uid);check(r);toast('SANCTION CLEARED')}

    function wireRealtime(){if(netChannel)sb.removeChannel(netChannel);netChannel=sb.channel('pj-network-v4-live').on('postgres_changes',{event:'INSERT',schema:'public',table:'net_notifications',filter:`recipient_id=eq.${user.id}`},async()=>{await loadUnread();playSound();if(currentTab==='notifications')loadNotifications();else toast('NEW NETWORK NOTIFICATION')}).on('postgres_changes',{event:'*',schema:'public',table:'net_xp'},async()=>{await loadBase();if(currentTab==='home')renderHome();if(currentTab==='id')renderId()}).on('postgres_changes',{event:'*',schema:'public',table:'net_build_requests'},()=>{if(currentTab==='builds')renderBuilds()}).on('postgres_changes',{event:'*',schema:'public',table:'net_events'},()=>{if(currentTab==='events')renderEvents()}).subscribe()}
    function parseLoungeText(raw){const s=String(raw||'');if(s.startsWith('~PJL3~')){try{return JSON.parse(s.slice(6)).text||''}catch(_){return''}}if(s.startsWith('~PJR3~')||s.startsWith('~PJS3~'))return'';return s}
    function wireMentionBridges(){const bridge=sb.channel('pj-network-v4-bridges');bridge.on('postgres_changes',{event:'INSERT',schema:'public',table:'lounge_messages'},async({new:r})=>{if(r.user_id!==user.id)return;const text=parseLoungeText(r.message);if(text)await handleMentions(text,'lounge',r.id);if(String(r.message||'').startsWith('~PJL3~')){try{const p=JSON.parse(String(r.message).slice(6));if(p.reply?.id){const original=await sb.from('lounge_messages').select('user_id').eq('id',p.reply.id).maybeSingle();if(!original.error&&original.data)await notify(original.data.user_id,'reply','lounge',r.id,`${me.displayName} replied to your Lounge message.`)}}catch(_){}}}).subscribe();const social=sb.channel('pj-network-v4-social-bridges').on('postgres_changes',{event:'INSERT',schema:'public',table:'follows'},async({new:r})=>{if(r.follower_id===user.id)await notify(r.following_id,'follow','profile',user.id,`${me.displayName} followed you.`)}).on('postgres_changes',{event:'INSERT',schema:'public',table:'topic_room_messages'},async({new:r})=>{if(r.user_id===user.id&&r.body)await handleMentions(r.body,'room',r.room)}).subscribe();window.addEventListener('beforeunload',()=>{try{sb.removeChannel(bridge);sb.removeChannel(social)}catch(_){}})}

    async function completeChallengeQuiet(id){const r=await sb.from('net_challenge_completions').insert({challenge_id:id,user_id:user.id});if(r.error&&!/duplicate/i.test(r.error.message))console.warn(r.error.message)}
    async function autoChallenges(){try{if(sessionStorage.getItem('pjArchiveSignalSeen'))await completeChallengeQuiet('archive-scout')}catch(_){};const dm=await sb.from('net_dm_messages').select('id',{count:'exact',head:true}).eq('sender_id',user.id);if(!dm.error&&dm.count>0)await completeChallengeQuiet('meet-community')}
    function enhanceProjectCards(){document.querySelectorAll('.project-card:not(.coming-soon)').forEach(card=>{if(card.querySelector('[data-pjn-project]'))return;const title=card.querySelector('h3')?.textContent?.trim();if(!title)return;const b=document.createElement('button');b.type='button';b.dataset.pjnProject='1';b.className='pjx-share';b.textContent='COMMUNITY COMMENTS ↗';b.style.marginTop='8px';b.onclick=()=>{open();switchTab('builds');setTimeout(()=>{const box=$(`[data-comments="project:${slug(title)}"]`);box?.scrollIntoView({behavior:'smooth',block:'center'})},250)};(card.querySelector('.pjx-actions')||card).appendChild(b)})}

    function registerPWA(){if(!document.querySelector('link[rel="manifest"]')){const l=document.createElement('link');l.rel='manifest';l.href='manifest.webmanifest?v=20261013-1';document.head.appendChild(l)}if('serviceWorker'in navigator)navigator.serviceWorker.register('service-worker.js?v=20261013-1').catch(()=>{});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e})}
    async function installApp(){if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else toast('USE YOUR BROWSER MENU → ADD TO HOME SCREEN / INSTALL APP')}

    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.classList.contains('open'))close();if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='n'){e.preventDefault();overlay.classList.contains('open')?close():open()}});
    window.PJNetwork={open,close,switchTab,get state(){return{connected,uid:user?.id||null,admin,unread,tab:currentTab}}};
    connect();
  });
})();